class Solution {
  public String maximumXor(String s, String t) {
    int ones = 0, zeros = 0;
    for (int i = 0; i < t.length(); i++) if (t.charAt(i) == '1') ones++;
    zeros = t.length() - ones;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
      boolean wantOne = s.charAt(i) == '0';
      if (wantOne ? ones > 0 : zeros > 0) {
        sb.append('1');
        if (wantOne) ones--;
        else zeros--;
      } else {
        sb.append('0');
        if (wantOne) zeros--;
        else ones--;
      }
    }
    return sb.toString();
  }
}
